import React, { useState } from "react";
import "./ProfitabilityResults.css";
import logo_moreinfo from "../ProfitabilityResults/assets/moreInfo.png";

const ProfitabilityResults = () => {
  const [showInfo, setShowInfo] = useState(false);

  const invoiceProfitability = {
    charge: "$0.00",
    expectedIncome: "$0.00",
    realIncome: "$0.00",
    hours: "1:00",

    projectedHours: "100 horas",
    realHours: "100 horas",

    overallProfitability: "0%",
  };

  return (
    <div
      style={{
        background: "#EEF1FF",
        borderRadius: "12px",
        padding: "16px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        position: "relative",
        maxWidth: "700px",
      }}
    >
      {/* Columna izquierda */}
      <div>
        <div>
          <strong>Cobro:</strong> {invoiceProfitability.charge}
        </div>

        <div>
          <strong>Ingreso OB:</strong> {invoiceProfitability.expectedIncome}
        </div>

        <div>
          <strong>Ingreso real:</strong> {invoiceProfitability.realIncome}
        </div>

        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "6px",
            position: "relative",
          }}
        >
          <span>
            <strong>Horas:</strong> {invoiceProfitability.hours}
          </span>

          <img
            src={logo_moreinfo}
            alt="Más información"
            onClick={() => setShowInfo(!showInfo)}
            style={{
              width: "16px",
              height: "16px",
              cursor: "pointer",
            }}
          />

          {showInfo && (
            <div
              style={{
                position: "absolute",
                bottom: "35px",
                left: "0",
                background: "#fff",
                border: "2px solid #4C8DFF",
                borderRadius: "12px",
                padding: "12px",
                minWidth: "220px",
                boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                zIndex: 10,
              }}
            >
              <div>
                <strong>Horas proyectadas:</strong>{" "}
                {invoiceProfitability.projectedHours}
              </div>

              <div>
                <strong>Horas reales:</strong>{" "}
                {invoiceProfitability.realHours}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Separador vertical */}
      <div
        style={{
          width: "1px",
          height: "70px",
          background: "#BFC6D8",
        }}
      />

      {/* Columna derecha */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "20px",
        }}
      >
        <div>
          <strong>Rentabilidad:</strong>{" "}
          {invoiceProfitability.overallProfitability}
        </div>

        <button className="See-graphic"
          style={{
            background: "#4C8DFF",
            color: "#fff",
            border: "none",
            borderRadius: "10px",
            padding: "10px 16px",
            cursor: "pointer",
          }}
        >
          Ver gráfico...
        </button>
      </div>
    </div>
  );
};

export default ProfitabilityResults;
